// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // The call may or may not revert; we only consider non-reverting executions.
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            assertTrue(ret);
        } catch {
            // Revert is acceptable; no assertion needed.
        }
    }
}
